import logging

import algokit_utils

logger = logging.getLogger(__name__)


# Deploys EvidenceRegistry and funds its account so it can pay for box storage.
# The typed client is generated by `algokit project run build`.
def deploy() -> None:
    from smart_contracts.artifacts.evidence_registry.evidence_registry_client import (
        EvidenceRegistryFactory,
    )

    algorand = algokit_utils.AlgorandClient.from_environment()
    deployer_ = algorand.account.from_environment("DEPLOYER")

    factory = algorand.client.get_typed_app_factory(
        EvidenceRegistryFactory, default_sender=deployer_.address
    )

    app_client, result = factory.deploy(
        on_update=algokit_utils.OnUpdate.AppendApp,
        on_schema_break=algokit_utils.OnSchemaBreak.AppendApp,
    )

    if result.operation_performed in [
        algokit_utils.OperationPerformed.Create,
        algokit_utils.OperationPerformed.Replace,
    ]:
        # Box storage needs a minimum balance held by the app account.
        algorand.send.payment(
            algokit_utils.PaymentParams(
                amount=algokit_utils.AlgoAmount(algo=1),
                sender=deployer_.address,
                receiver=app_client.app_address,
            )
        )

    logger.info(
        f"{app_client.app_name} deployed: app id {app_client.app_id}, "
        f"address {app_client.app_address} "
        f"({result.operation_performed.name})"
    )
